// Command legagent 啟動立法委員服務 Agent 的 gRPC 伺服器，並提供 ingest 子命令建置議事規則索引。
//
//	go run .                          # 啟動 gRPC 伺服器
//	go run . ingest [flags]           # 下載法規 → data/laws → 向量索引（見 ingest.go）
//	go run . import-legislators       # 立委名單寫入 PostgreSQL（見 import_legislators.go）
//	go run . import-laws [flags]      # 全部法規寫入 PostgreSQL，每部一張表（見 import_laws.go）
//	go run . -config path/config.yaml # 指定設定檔（ingest 亦支援 -config）
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 組裝 config → logger → embedding → 向量庫 → service → gRPC，不含業務邏輯
package main

import (
	"flag"
	"fmt"
	"net"
	"os"
	"os/signal"
	"regexp"
	"syscall"

	"google.golang.org/grpc"
	"google.golang.org/grpc/reflection"
	"gopkg.in/yaml.v3"

	hypconfig "github.com/maoxiaoyue/hypgo/pkg/config"
	"github.com/maoxiaoyue/hypgo/pkg/hidb"
	"github.com/maoxiaoyue/hypgo/pkg/hidb/pg"
	"github.com/maoxiaoyue/hypgo/pkg/logger"
	"github.com/maoxiaoyue/hypgo/pkg/manifest"
	"github.com/maoxiaoyue/hypgo/pkg/router"

	pb "legagent/app/proto/legagentpb"
	"legagent/app/rpc"
	"legagent/app/services"
	"legagent/internal/embed"
	"legagent/internal/vectorstore"
)

const defaultConfigPath = "config/config.yaml"

func main() {
	if len(os.Args) > 1 {
		switch os.Args[1] {
		case "ingest":
			runIngest(os.Args[2:])
			return
		case "import-legislators":
			runImportLegislators(os.Args[2:])
			return
		case "import-laws":
			runImportLaws(os.Args[2:])
			return
		}
	}
	cfgPath := flag.String("config", defaultConfigPath, "config.yaml 路徑")
	flag.Parse()
	runServer(*cfgPath)
}

// runServer 啟動 gRPC 伺服器並阻塞至收到 SIGINT / SIGTERM。
//
// @ai:generated by=claude-opus-5-5 date=2026-10-20
// @ai:purpose 與 ingest 子命令共用同一份設定與向量庫組裝流程
// @ai:input cfgPath 設定檔路徑
// @ai:output none
// @ai:sideeffect 監聽 TCP、寫入 .hyp/context.yaml、失敗時 os.Exit
func runServer(cfgPath string) {
	cfg, log := mustLoad(cfgPath)
	rules, store := mustOpenRules(cfg, log)
	if store.Count() == 0 {
		log.Warn("rule index is empty; run: go run . ingest")
	}

	lis, err := net.Listen("tcp", cfg.GRPC.Addr)
	if err != nil {
		log.Error("listen failed", "addr", cfg.GRPC.Addr, "err", err)
		os.Exit(1)
	}

	s := grpc.NewServer(
	// Interceptor（中間件）可在此加入：
	// grpc.ChainUnaryInterceptor(interceptor.Recovery(log), interceptor.Logger(log)),
	)
	pb.RegisterLegagentServiceServer(s, rpc.NewLegagentServer(rules, log))

	// 註冊 Schema（Protocol "grpc"；供 hyp context / contract.TestAll 理解服務介面）
	rpc.RegisterSchemas()

	// 同步 manifest 到 .hyp/context.yaml（gRPC 不走 server.Start 的 AutoSync，故啟動時主動寫一次）
	manifest.NewAutoSync(manifest.AutoSyncConfig{Enabled: true}, router.New(), nil, nil).SyncSafe()

	// 啟用 gRPC reflection（方便 grpcurl 偵錯）
	reflection.Register(s)

	log.Info("gRPC server listening", "addr", cfg.GRPC.Addr)
	go func() {
		if err := s.Serve(lis); err != nil {
			log.Error("serve failed", "err", err)
			os.Exit(1)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	log.Info("shutting down gRPC server")
	s.GracefulStop()
	log.Info("server stopped")
}

// mustLoad 載入設定並依 logger 區段建立 logger；失敗時記錄後結束程式。
func mustLoad(cfgPath string) (*appConfig, *logger.Logger) {
	cfg, err := loadConfig(cfgPath)
	if err != nil {
		boot, _ := logger.New("error", "stderr", nil, false)
		boot.Error("load config failed", "path", cfgPath, "err", err)
		os.Exit(1)
	}
	log, _ := logger.New(cfg.Logger.Level, cfg.Logger.Output, nil, cfg.Logger.Colors)
	return cfg, log
}

// mustOpenRules 依設定建立 embedding 與向量庫並組出 RulesService；失敗時記錄後結束程式。
//
// @ai:generated by=claude-opus-5-5 date=2026-10-20
// @ai:purpose 伺服器與 ingest 必須用同一組 embedding/向量庫參數，避免兩邊各自組裝而漂移
// @ai:input cfg 設定, log
// @ai:output *services.RulesService, vectorstore.Store
// @ai:sideeffect 開啟或建立 vector.path 目錄、失敗時 os.Exit
func mustOpenRules(cfg *appConfig, log *logger.Logger) (*services.RulesService, vectorstore.Store) {
	embedder, desc, err := embed.New(embed.Config{
		Provider: cfg.Embedding.Provider, BaseURL: cfg.Embedding.BaseURL,
		APIKey: cfg.Embedding.APIKey, Model: cfg.Embedding.Model,
	})
	if err != nil {
		log.Error("build embedder failed", "err", err)
		os.Exit(1)
	}
	store, err := vectorstore.NewChromem(vectorstore.Options{
		Path: cfg.Vector.Path, Collection: cfg.Vector.Collection, Compress: cfg.Vector.Compress,
		Metadata: map[string]string{"embedding": desc},
	}, embedder)
	if err != nil {
		log.Error("open vector store failed", "path", cfg.Vector.Path, "err", err)
		os.Exit(1)
	}
	log.Info("vector store ready", "path", cfg.Vector.Path, "collection", cfg.Vector.Collection, "documents", store.Count(), "embedder", desc)
	return services.NewRulesService(store, cfg.Rules.DataDir, log, cfg.Embedding.Concurrency), store
}

// mustOpenDB 連上 PostgreSQL；只啟用 SQL 方言，不會連 Redis。失敗時記錄後結束程式。
func mustOpenDB(cfg *appConfig, log *logger.Logger) *hidb.Database {
	db, err := hidb.NewWithInterface(&cfg.Database, hidb.WithDialect(pg.New()))
	if err != nil {
		log.Error("connect database failed", "err", err)
		os.Exit(1)
	}
	return db
}

// appConfig 對應 config/config.yaml。HypGo 的 config.Config 只涵蓋 server/db/logger，
// 且不展開環境變數，而 embedding 金鑰必須走環境變數，故在此自行解析。
type appConfig struct {
	GRPC struct {
		Addr string `yaml:"addr"`
	} `yaml:"grpc"`
	Logger struct {
		Level  string `yaml:"level"`
		Output string `yaml:"output"`
		Colors bool   `yaml:"colors"`
	} `yaml:"logger"`
	Database  hypconfig.DatabaseConfig `yaml:"database"`
	Embedding struct {
		Provider    string `yaml:"provider"`
		BaseURL     string `yaml:"base_url"`
		APIKey      string `yaml:"api_key"`
		Model       string `yaml:"model"`
		Concurrency int    `yaml:"concurrency"`
	} `yaml:"embedding"`
	Vector struct {
		Path       string `yaml:"path"`
		Collection string `yaml:"collection"`
		Compress   bool   `yaml:"compress"`
	} `yaml:"vector"`
	Rules struct {
		DataDir          string   `yaml:"data_dir"`
		CacheDir         string   `yaml:"cache_dir"`
		CacheMaxAgeHours int      `yaml:"cache_max_age_hours"`
		CategoryPrefixes []string `yaml:"category_prefixes"`
		Names            []string `yaml:"names"`
		ExcludeRepealed  bool     `yaml:"exclude_repealed"`
	} `yaml:"rules"`
}

// reEnv 支援 ${VAR} 與 ${VAR:-default}。
var reEnv = regexp.MustCompile(`\$\{([A-Za-z_][A-Za-z0-9_]*)(?::-([^}]*))?\}`)

// loadConfig 讀取 YAML、展開環境變數並補上預設值。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 單一入口載入設定，確保伺服器與 ingest 讀到同一份值；金鑰不得寫死在 YAML
// @ai:input path config.yaml 路徑
// @ai:output *appConfig, error
// @ai:sideeffect 讀檔、讀環境變數
func loadConfig(path string) (*appConfig, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", path, err)
	}
	expanded := reEnv.ReplaceAllStringFunc(string(raw), func(m string) string {
		sub := reEnv.FindStringSubmatch(m)
		if v := os.Getenv(sub[1]); v != "" {
			return v
		}
		return sub[2]
	})
	var c appConfig
	if err := yaml.Unmarshal([]byte(expanded), &c); err != nil {
		return nil, fmt.Errorf("parse %s: %w", path, err)
	}
	setDefault(&c.GRPC.Addr, ":9090")
	setDefault(&c.Logger.Level, "info")
	setDefault(&c.Logger.Output, "stdout")
	setDefault(&c.Embedding.Provider, embed.ProviderLexical)
	setDefault(&c.Vector.Path, "data/vectors")
	setDefault(&c.Vector.Collection, "ly_rules")
	setDefault(&c.Rules.DataDir, "data/laws")
	setDefault(&c.Rules.CacheDir, "data/raw")
	if c.Embedding.Concurrency <= 0 {
		c.Embedding.Concurrency = 4
	}
	if c.Rules.CacheMaxAgeHours == 0 {
		c.Rules.CacheMaxAgeHours = 720
	}
	if len(c.Rules.CategoryPrefixes) == 0 && len(c.Rules.Names) == 0 {
		c.Rules.CategoryPrefixes = []string{"立法"}
	}
	return &c, nil
}

func setDefault(s *string, v string) {
	if *s == "" {
		*s = v
	}
}
